#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>
#include <algorithm>

// Big-number Fibonacci (C++ part). Digits stored little-endian.
static std::vector<int> add(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> r;
    int carry = 0;
    for (size_t i = 0; i < std::max(a.size(), b.size()) || carry; ++i) {
        int s = carry;
        if (i < a.size()) s += a[i];
        if (i < b.size()) s += b[i];
        r.push_back(s % 10);
        carry = s / 10;
    }
    return r;
}

int main(int argc, char** argv) {
    long n = argc > 1 ? std::atol(argv[1]) : 0;
    std::vector<int> a(1, 1), b(1, 1);
    for (long i = 0; i < n; ++i) {
        std::vector<int> c = add(a, b);
        a = b;
        b = c;
    }
    std::string s;
    for (size_t i = a.size(); i-- > 0;) s.push_back(char(48 + a[i]));
    std::printf("%s\n", s.c_str());
    return 0;
}
